import java.util.*;

class Solution {
    public boolean canFinish(int[] stones) {
        int farthest = 0;
        for (int i = 0; i < stones.length; i++) {
            if (i > farthest) return false;            // this stone can't be reached
            farthest = Math.max(farthest, i + stones[i]);
            if (farthest >= stones.length - 1) return true;
        }
        return true;
    }
}

